class PerfBench:
    """Reusable performance benchmark for "big fights": a headless simulation benchmark and an offscreen
rendering benchmark that drives the real UI (GameScreen, lindefense.ui.WorldView, the real
sprites) inside a real GCanvas and paints it into a BufferedImage, exactly like the demo
driver's snapshots. Nothing is ever shown on screen and nothing is screen-captured; the JVM runs with
java.awt.headless=true unless told otherwise.

Scenarios

  sim: on every map, a dense roster of maxed towers (all 20 types, cycled; heroes once) plays the
      late waves perf.from..perf.to for real (leaks never end the run). Abilities fire every second.
      Reports ms per Game#step (mean / p50 / p95 / p99 / max), enemy / projectile / effect counts,
      visual events per tick, bytes allocated per tick and GC activity, plus an outcome fingerprint
      (kills, leaks, cash, per-tower damage) that must be identical for identical code paths.
  siege (part of sim): a real late wave plus a crowd kept at N enemies on every map, the worst case for
      targeting, collisions, splash, chains and statuses.
  render: one map, the same dense maxed roster, and a crowd of exactly N enemies (mixed types and
      modifiers, a third of them killable so deaths and splits happen) kept topped up while the towers fire.
      Each frame runs GameScreen.frame(1/60) (one sim step plus the UI sync) and then paints the whole
      canvas. Reports update ms, paint ms and total ms per frame (mean / p95 / max), the number of live
      GObjects in the scene graph and bytes allocated per frame.

Usage

  java -cp build:lib/acm.jar lindefense.tools.PerfBench [sim|render|all]
  scripts/perfbench.sh [sim|render|all]           (builds first; PERF_JFR=1 adds a JFR recording + hot methods)

Options (system properties): perf.maps=0,1,2,3, perf.from=90, perf.to=100,
perf.waveSeconds=30 (sim seconds per wave), perf.towers=72 (roster size), perf.seed=1234,
perf.siege=400 (siege crowd size, 0 = skip), perf.siegeWave=96, perf.siegeSeconds=20, perf.siegeHp=8,
lindefense.difficulty=O1|ON|ON2|ONN, perf.enemies=150,300,600 (render crowd sizes),
perf.frames=240, perf.renderMap=0, perf.size=1600x1000 (canvas pixels),
perf.clock=cpu|wall (default cpu: benchmark-thread CPU time, robust on a busy machine),
perf.snap=<dir> (PNG of the last frame of each render case), perf.breakdown=true (per-layer and
per-sprite-class paint cost of the final scene), perf.warmup=true."""
    class SimRun:
        """Per-tick timing and load counters for one simulation run."""
        def __init__(self, g):
            self.g = None
            self.enemy_sum = 0
            self.events = 0
            self.enemy_max = 0
            self.proj_max = 0
            self.fx_max = 0
            self.st = PerfBench.Stats()
            self.gc0 = PerfBench.gc_count()
            self.alloc0 = PerfBench.alloc_bytes()
            self.g = g
        def tick(self, tick):
            """One measured tick: abilities every second, then Game#step."""
            t0 = PerfBench.now()
            if _j.imod(tick, 60) == 0:
                PerfBench.fire_abilities(self.g)
            self.g.step(Game.DT)
            self.st.add(((PerfBench.now() - t0) / 1e6))
            en = len(self.g.get_enemy_manager().get_enemies())
            self.enemy_sum += en
            self.enemy_max = max(self.enemy_max, en)
            self.proj_max = max(self.proj_max, len(self.g.get_combat().get_projectiles()))
            self.fx_max = max(self.fx_max, PerfBench.effect_count(self.g))
            self.events += len(self.g.get_events())
            self.g.get_events().clear()
        def row(self):
            bytes_ = (PerfBench.alloc_bytes() - self.alloc0)
            return _j.format('%-26s %6d %8.3f %7.3f %7.3f %7.3f %7.2f | %5d %5d %5d %5d %6.1f | %8.1f %6d | %s', self.g.get_map().get_name(), self.st.n, self.st.mean(), self.st.pct(50), self.st.pct(95), self.st.pct(99), self.st.max(), _j.idiv(self.enemy_sum, max(1, self.st.n)), self.enemy_max, self.proj_max, self.fx_max, (self.events / float(max(1, self.st.n))), ((bytes_ / 1024.0) / max(1, self.st.n)), (PerfBench.gc_count() - self.gc0), PerfBench.fingerprint(self.g))
    class RenderRig:
        """The real UI stack (GCanvas -> ScaledLayer -> GameScreen) painted offscreen into a BufferedImage."""
        def __init__(self, game, w, h):
            self.game = None
            self.screen = None
            self.img = None
            self.canvas = GCanvas()
            self.root = ScaledLayer()
            self.game = game
            self.canvas.set_size(w, h)
            self.canvas.set_background(Ui.BG)
            PerfBench.configure_like_program(self.canvas)
            self.canvas.add(self.root)
            self.root.fit(w, h)
            self.screen = GameScreen(None, game)
            self.root.add(self.screen)
            self.img = BufferedImage(w, h, BufferedImage.TYPE_INT_RGB)
        def paint(self):
            """Paints the whole canvas exactly like the demo driver's snapshot (GCanvas.paint into a Graphics2D)."""
            g2 = self.img.create_graphics()
            try:
                self.canvas.paint(g2)
            finally:
                g2.dispose()
        def paint_ms(self, k):
            """Mean paint time of the current scene over k paints (no updates in between)."""
            t0 = PerfBench.now()
            for i in range(k):
                self.paint()
            return ((PerfBench.now() - t0) / 1e6) / k
    class Stats:
        """Sample collector with mean / percentiles / max."""
        def __init__(self):
            self.n = 0
            self.sum = 0.0
            self.v = ([0.0] * 1024)
            pass
        def add(self, x):
            if self.n == len(self.v):
                self.v = _j.copy_of(self.v, (self.n * 2), 0.0)
            self.v[_j_postinc(self, 'n', 1)] = x
            self.sum += x
        def add_all(self, o):
            i = 0
            while i < o.n:
                self.add(o.v[i])
                i += 1
        def mean(self):
            return 0 if (self.n == 0) else (self.sum / self.n)
        def max(self):
            m = 0.0
            for i in range(self.n):
                m = _j.dmax(m, self.v[i])
            return m
        def pct(self, p):
            if self.n == 0:
                return 0.0
            s = _j.copy_of(self.v, self.n, 0.0)
            _j.sort_range(s)
            return s[min((self.n - 1), (_j.to_int(float(math.ceil(((p / 100.0) * self.n)))) - 1))]
